patch:
diff --git a/tests/repro/win-cross-drive-ignore.js b/tests/repro/win-cross-drive-ignore.js
new file mode 100644
index 0000000..bc4e1b3
--- /dev/null
+++ b/tests/repro/win-cross-drive-ignore.js
@@ -0,0 +1,62 @@
+/**
+ * Repro for "files on a different drive are not ignored on Windows".
+ * SIMULATED Windows (on non-win32 hosts): after ESLint and all core rules are
+ * loaded, node:path is swapped for path.win32 and cwd is set to C:\Project.
+ * On real Windows the patch is skipped and the real cwd is used.
+ * Run: node tests/repro/win-cross-drive-ignore.js
+ */
+/* eslint-disable no-console -- repro script output */
+"use strict";
+
+const path = require("node:path");
+const { Linter, ESLint } = require("../../lib/api");
+const builtinRules = require("../../lib/rules");
+
+if (process.platform !== "win32") {
+
+    /*
+     * Load everything lazily required (all core rules) while module resolution
+     * still uses posix paths, then switch the shared `path` module to win32.
+     */
+    for (const [, rule] of builtinRules) {
+        void rule;
+    }
+    Object.assign(path, path.win32);
+    process.cwd = () => "C:\\Project";
+}
+
+const cwd = process.cwd();
+const sameDrive = "C:\\foo.js"; // outside cwd, same drive  -> control
+const otherDrive = "F:\\foo.js"; // outside cwd, other drive -> reported case
+
+(async () => {
+    console.log(`platform=${process.platform} simulatedWin32=${process.platform !== "win32"} cwd=${cwd}`);
+    console.log(`path.relative(cwd, ${sameDrive})  = ${JSON.stringify(path.relative(cwd, sameDrive))}`);
+    console.log(`path.relative(cwd, ${otherDrive}) = ${JSON.stringify(path.relative(cwd, otherDrive))}`);
+
+    // 1) Linter, exactly as in the report
+    const linter = new Linter({ configType: "flat" });
+    const config = { rules: { "no-undef": "error" } };
+
+    for (const file of [sameDrive, otherDrive]) {
+        const msgs = linter.verify("foo()", config, file);
+
+        console.log(`\n[Linter.verify] ${file}:`, msgs.map(m => `${m.ruleId ?? "(no rule)"}: ${m.message}`));
+    }
+
+    // 2) ESLint class, equivalent of `eslint --no-config-lookup --rule "no-undef: error" <file>`
+    const eslint = new ESLint({ cwd, overrideConfigFile: true, overrideConfig: config });
+
+    for (const file of [sameDrive, otherDrive]) {
+        const ignored = await eslint.isPathIgnored(file);
+        const [result] = await eslint.lintText("foo();", { filePath: file, warnIgnored: true });
+
+        console.log(`\n[ESLint] ${file}: isPathIgnored=${ignored}`, result.messages.map(m => `${m.ruleId ?? "(no rule)"}: ${m.message}`));
+    }
+
+    const otherIgnored = await eslint.isPathIgnored(otherDrive);
+
+    console.log(`\nRESULT: ${otherIgnored ? "NOT reproduced (other-drive file ignored)" : "BUG REPRODUCED: file on another drive is not ignored"}`);
+    process.exitCode = otherIgnored ? 0 : 1;
+})();
+/* eslint-enable no-console -- end of repro script */
